    const refused = await stored(id); assert.deepEqual(refused.media, before.media); assert.equal(refused.revision, before.revision); assert.equal(refused.recoveryReceipts?.length ?? 0, 0);
    await assert.rejects(uploadAdminImportAsset(other.toHexString(), id, slotId, mutation(1), file(), storage), code('ADMIN_IMPORT_ASSET_EXISTS'));
    // The late attempt lands inside the window; after the deadline, cleanup removes that exact object.
    land(storage, id, before.media!.assets[0]);
