test('embedded covers: identical images are staged once and distinct images are bounded per import', async () => {
    const shared = await sharp({ create: { width: 2, height: 2, channels: 3, background: '#fa8' } }).png().toBuffer();
    for (const [covers, embedded] of [[Array<Buffer>(100).fill(shared), 1], [await distinctCovers(), 16]] as const) {
        const storage = new Storage(), { project, intents, upload } = await hundredTagged(storage, [...covers]), doc = await stored(project.item.id);
        const candidates = project.item.assets.filter(asset => asset.slotId.startsWith('embedded-'));
        assert.equal(project.item.assets.length, 100 + embedded); assert.equal(storage.objects.size, 100 + embedded); assert.equal(candidates.length, embedded);
        assert.equal(candidates.every(asset => asset.state === 'ready' && asset.recovery!.kind === 'upload'), true); assert.equal(new Set(candidates.map(asset => asset.sha256)).size, embedded);
        assert.equal(doc.automaticReceipts!.length, embedded); assert.equal(doc.receipts.length, 101); assert.equal(project.item.receipts.length, 101);
        const puts = storage.puts, replay = await upload(0, intents[0]);
        assert.equal(replay.item.assets.length, 100 + embedded); assert.equal(storage.puts, puts); assert.equal((await stored(project.item.id)).automaticReceipts!.length, embedded);
    }
});
test('receipt budget: 100 files with shared or distinct covers, re-uploads after confirmed failures, edits, decisions and approval stay below 256 ordinary receipts', async () => {
    const shared = await sharp({ create: { width: 2, height: 2, channels: 3, background: '#fa8' } }).png().toBuffer(), failing = new Set([3, 50, 99]);
    for (const [covers, embedded] of [[Array<Buffer>(100).fill(shared), 1], [await distinctCovers(), 16]] as const) {
        const storage = new Storage(), staged = await hundredTagged(storage, [...covers], failing), id = staged.project.item.id; let project = staged.project;
        for (const index of failing) {
            assert.equal(project.item.assets.find(asset => asset.slotId === staged.sources[index].slotId)!.state, 'unknown');
            await reconcile(id, staged.sources[index].slotId, staged.intents[index].operationId, storage, later());
            project = await staged.upload(index, mutation(1)); assert.equal(project.item.assets.find(asset => asset.slotId === staged.sources[index].slotId)!.state, 'ready');
        }
        // Every confirmed upload prefilled its own values, and the album step shared the last confirmation's run: automatic writes
        // count in valueRevision and take no receipt of either kind.
        const prefilled = await stored(id), draft = prefilled.draft as ImportDraftV2;
        assert.deepEqual([draft.album.title, draft.album.artists.map(entry => [entry.name, entry.role]), draft.album.releaseDate, draft.tracks.slice(0, 2).map(track => [track.title, track.trackNumber])],
            ['Tagged Budget Album', [['Tagged Ensemble', 'primary']], { year: 2026, month: null, day: null }, [['Tagged 0', 1], ['Tagged 1', 2]]]);
        assert.deepEqual([prefilled.valueRevision, prefilled.receipts.length, prefilled.automaticReceipts!.length], [100, 1 + 100 + failing.size, embedded]);
        for (let edit = 0; edit < 10; edit++) {
            project = await editImportDraft(actor.toHexString(), id, project.item, draft => {
                draft.album.title = `Budget Album ${edit}`; if (!draft.album.artists.length) draft.album.artists = artistEntries('Synthetic Artist');
                draft.tracks.forEach((track, index) => { track.title = `Track ${index}`; track.trackNumber = index + 1; });
            });
        }
        const fresh = (scope: 'artist' | 'album' | 'track', slotId: string | null = null) => ({ scope, slotId, boundName: null as string | null, action: 'create-distinct', candidateId: null, candidateRevision: null });
        project = await decideAdminImportDuplicates(actor.toHexString(), id, { ...mutation(project.item.revision), decisions: withEntryKeys(project.item.draft, [fresh('artist'), fresh('album'), ...project.item.manifest.files.map(file => fresh('track', file.slotId))]) });
        project = await publishAdminImport(actor.toHexString(), id, approvalBody(project.item)); assert.equal(project.item.publication, 'preparing');
        const doc = await stored(id);
        assert.equal(doc.receipts.length, 1 + 100 + failing.size + 10 + 1 + 1); assert.ok(doc.receipts.length < 256);
        assert.equal(doc.receipts.filter(receipt => receipt.kind === 'upload').length, 103); assert.equal(doc.automaticReceipts!.length, embedded);
        assert.equal(doc.receipts.some(receipt => doc.automaticReceipts!.some(automatic => automatic.operationId === receipt.operationId)), false);
    }
});
/** A folderless one-file import whose manifest leaves the size open, so audio carrying different embedded images can replace it. */
async function taggedProject() {
    const slotId = randomUUID(), filename = 'Tagged.wav';
    const created = await createAdminImport(actor.toHexString(), { operationId: randomUUID(), manifest: { rootLabel: '', files: [{ slotId, filename, relativePath: filename, byteLength: null }] } });
    const audio = (png: Buffer) => { const bytes = taggedWav(png); return { ...file(), buffer: bytes, size: bytes.length, originalname: filename }; };
    return { id: created.item.id, slotId, audio };
}
const pngOf = (background: string) => sharp({ create: { width: 2, height: 2, channels: 3, background } }).png().toBuffer();

test('reconcile refuses missing projects, catalog reviews and non-upload lifecycles, and leaves a ready upload untouched', async () => {
    const storage = new Storage(), created = await create(), id = created.item.id, slotId = created.item.manifest.files[0].slotId, intent = mutation(1);
    await assert.rejects(reconcile(new ObjectId().toHexString(), slotId, intent.operationId, storage), code('ADMIN_IMPORT_NOT_FOUND'));
    await assert.rejects(reconcile(id, slotId, intent.operationId, storage), code('ADMIN_IMPORT_ASSET_CONFLICT'));
    const uploaded = await uploadAdminImportAsset(actor.toHexString(), id, slotId, intent, file(), storage), heads = storage.heads;
    const ready = await reconcile(id, slotId, intent.operationId, storage, later());
    assert.equal(ready.item.revision, uploaded.item.revision); assert.deepEqual(ready.receipt, { operationId: intent.operationId, kind: 'upload', revision: 2 }); assert.equal(storage.heads, heads);
    // A staged copy being removed belongs to its cleanup lifecycle, never to an upload of unknown outcome.
    storage.failDelete = true; const removal = mutation(ready.item.revision);
    assert.equal((await cleanupAdminImportAsset(actor.toHexString(), id, slotId, removal, storage)).item.assets[0].state, 'cleanupFailed');
    for (const operationId of [intent.operationId, removal.operationId]) await assert.rejects(reconcile(id, slotId, operationId, storage, later()), code('ADMIN_IMPORT_ASSET_CONFLICT'));
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(id) }, { $set: { 'media.assets.0.state': 'deleting', 'media.assets.0.recovery': { ...intent, kind: 'upload', actorId: actor.toHexString() } } });
    const before = await stored(id), checks = storage.heads; await assert.rejects(reconcile(id, slotId, intent.operationId, storage, later()), code('ADMIN_IMPORT_ASSET_CONFLICT'));
    assert.deepEqual(await stored(id), before); assert.equal(storage.heads, checks);
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(id) }, { $set: { purpose: 'catalogReview' } });
    await assert.rejects(reconcile(id, slotId, intent.operationId, storage), code('ADMIN_IMPORT_NOT_FOUND'));
});
